import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import { getBooks, addBook, getBook, finishBook } from './books.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));
app.use(express.urlencoded({ extended: true }));
app.use(express.static(path.join(__dirname, 'public')));

app.get('/', (req, res) => {
  const books = getBooks();
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  res.render('index', { reading, finished });
});

app.get('/books/:id', (req, res) => {
  const book = getBook(req.params.id);
  if (!book) return res.status(404).send('Book not found');
  res.render('book', { book });
});

app.post('/books', (req, res) => {
  const { title, author, notes } = req.body;
  addBook({ title, author, notes });
  res.redirect('/');
});

app.post('/books/:id/finish', (req, res) => {
  finishBook(req.params.id);
  res.redirect('/');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

export default app;

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import crypto from 'crypto';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DATA_FILE = path.join(__dirname, 'books.json');

function readBooks() {
  try {
    const data = fs.readFileSync(DATA_FILE, 'utf-8');
    return JSON.parse(data);
  } catch {
    return [];
  }
}

function writeBooks(books) {
  fs.writeFileSync(DATA_FILE, JSON.stringify(books, null, 2));
}

export function getBooks() {
  return readBooks();
}

export function getBook(id) {
  return readBooks().find((b) => b.id === id);
}

export function addBook({ title, author, notes }) {
  const books = readBooks();
  const book = {
    id: crypto.randomUUID(),
    title: title || '',
    author: author || '',
    notes: notes || '',
    finished: false,
    createdAt: new Date().toISOString(),
  };
  books.push(book);
  writeBooks(books);
  return book;
}

export function finishBook(id) {
  const books = readBooks();
  const book = books.find((b) => b.id === id);
  if (book) {
    book.finished = true;
    writeBooks(books);
  }
  return book;
}

