:root {
  --bg: #f9f9f9;
  --text: #222;
  --accent: #4f46e5;
  --accent-hover: #4338ca;
  --border: #ddd;
  --radius: 8px;
}

* { box-sizing: border-box; }

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  margin: 0;
  padding: 2rem 1rem;
}

.container {
  max-width: 640px;
  margin: 0 auto;
}

h1, h2 { margin: 0 0 0.75rem; }

section {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  margin-bottom: 1.25rem;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.book-list li {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
}

.book-list li:last-child { border-bottom: none; }

.book-list a {
  color: var(--accent);
  text-decoration: none;
  font-weight: 600;
}

.book-list a:hover { text-decoration: underline; }

.author { color: #666; }

.empty { color: #888; font-style: italic; margin: 0; }

form label {
  display: block;
  margin-bottom: 0.75rem;
  font-weight: 500;
}

form input,
form textarea {
  display: block;
  width: 100%;
  margin-top: 0.25rem;
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
}

button {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 0.5rem 1rem;
  font: inherit;
  cursor: pointer;
}

button:hover { background: var(--accent-hover); }

.inline { margin: 0; }

.status {
  display: inline-block;
  background: #e0e7ff;
  color: var(--accent);
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.875rem;
}

.notes {
  margin-top: 1.5rem;
}

.notes p {
  white-space: pre-wrap;
  margin: 0;
}

import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import app from '../app.js';
import { getBooks, finishBook } from '../books.js';

describe('Book Tracker', () => {
  beforeEach(() => {
    const books = getBooks();
    books.length = 0;
  });

  it('shows empty lists initially', async () => {
    const res = await request(app).get('/');
    expect(res.status).toBe(200);
    expect(res.text).toContain('Currently Reading');
    expect(res.text).toContain('No books currently reading');
  });

  it('adds a book and lists it under reading', async () => {
    await request(app)
      .post('/books')
      .type('form')
      .send({ title: 'Dune', author: 'Frank Herbert', notes: 'Great sci-fi' })
      .expect(302);

    const res = await request(app).get('/');
    expect(res.text).toContain('Dune');
    expect(res.text).toContain('Frank Herbert');
  });

  it('marks a book as finished', async () => {
    await request(app)
      .post('/books')
      .type('form')
      .send({ title: 'Dune', author: 'Frank Herbert', notes: '' });

    const book = getBooks()[0];
    await request(app)
      .post(`/books/${book.id}/finish`)
      .expect(302);

    const updated = getBooks().find((b) => b.id === book.id);
    expect(updated.finished).toBe(true);
  });

  it('shows book details', async () => {
    await request(app)
      .post('/books')
      .type('form')
      .send({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice' });

    const book = getBooks()[0];
    const res = await request(app).get(`/books/${book.id}`);
    expect(res.status).toBe(200);
    expect(res.text).toContain('Dune');
    expect(res.text).toContain('Frank Herbert');
    expect(res.text).toContain('Spice');
  });
});

